val newLevel = minOf((totalPoints / 100) + 1, medal.maxLevel)\n \n medal.copy(\n level = newLevel,\n points = totalPoints % 100, // Puntos restantes después del level up\n isLocked = false,\n hasLeveledUp = newLevel > medal.level,\n nextLevelGoal = when {\n newLevel >= medal.maxLevel -> \"¡Nivel máximo alcanzado!\"\n else -> \"Mantén ${100 - (totalPoints % 100)} días más de racha para subir de nivel\"\n }\n )\n } else {\n medal\n }\n }\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01AdjNN4oQCHQyvSknBVUvDe","content":"The apply model made the following changes to the file:

