data class AlbumMedal(
 val id: String,
 val name: String,
 val description: String,
 val icon: ImageVector,
 val rarity: MedalRarity,
 val isUnlocked: Boolean,
 val unlockedDate: String? = null,
 val category: String
)

enum class MedalRarity(val displayName: String, val color: Color) {
 COMMON("Común", Color(0xFF9E9E9E)),
 RARE("Rara", Color(0xFF2196F3)),
 EPIC("Épica", Color(0xFF9C27B0)),
 LEGENDARY("Legendaria", Color(0xFFFFD700))
}

@Composable
fun AlbumScreen() {
 val medals = remember {
 listOf(
 AlbumMedal(
 id = "first_steps",
 name = "Primeros Pasos",
 description = "Completa tu primera actividad",
 icon = Icons.Default.Star,
 rarity = MedalRarity.COMMON,
 isUnlocked = true,
 unlockedDate = "15 Oct 2024",
 category = "Principiante"
 ),
 AlbumMedal(
 id = "fire_starter",
 name = "Iniciador de Fuego",
 description = "Mantén una racha de 3 días",
 icon = Icons.Default.LocalFireDepartment,
 rarity = MedalRarity.COMMON,
 isUnlocked = true,
 unlockedDate = "16 Oct 2024",
 category = "Rachas"
 ),
 AlbumMedal(
 id = "early_riser",
 name = "Madrugador",
 description = "Completa 5 actividades antes de las 8 AM",
 icon = Icons.Default.Schedule,
 rarity = MedalRarity.RARE,
 isUnlocked = true,
 unlockedDate = "18 Oct 2024",
 category = "Tiempo"
 ),
 AlbumMedal(
 id = "strength_master",
 name = "Maestro de Fuerza",
 description = "Completa 50 ejercicios de fuerza",
 icon = Icons.Default.FitnessCenter,
 rarity = MedalRarity.RARE,
 isUnlocked = false,
 category = "Ejercicio"
 ),
 AlbumMedal(
 id = "streak_legend",
 name = "Leyenda de Rachas",
 description = "Mantén una racha de 30 días",
 icon = Icons.Default.Whatshot,
 rarity = MedalRarity.EPIC,
 isUnlocked = false,
 category = "Rachas"
 ),
 AlbumMedal(
 id = "progress_god",
 name = "Dios del Progreso",
 description = "Alcanza el nivel máximo en todas las medallas",
 icon = Icons.Default.TrendingUp,
 rarity = MedalRarity.EPIC,
 isUnlocked = false,
 category = "Progreso"
 ),
 AlbumMedal(
 id = "champion_of_champions",
 name = "Campeón de Campeones",
 description = "Desbloquea todas las medallas del álbum",
 icon = Icons.Default.EmojiEvents,
 rarity = MedalRarity.LEGENDARY,
 isUnlocked = false,
 category = "Logros"
 ),
 AlbumMedal(
 id = "verified_legend",
 name = "Leyenda Verificada",
 description = "Mantén una racha perfecta por 100 días",
 icon = Icons.Default.Verified,
 rarity = MedalRarity.LEGENDARY,
 isUnlocked = false,
 category = "Rachas"
 )
 )
 }

 val categories = remember {
 listOf("Todas", "Principiante", "Rachas", "Ejercicio", "Tiempo", "Progreso", "Logros")
 }

 var selectedTabIndex by remember { mutableStateOf(0) }

 val filteredMedals = remember(selectedTabIndex) {
 if (selectedTabIndex == 0) {
 medals
 } else {
 medals.filter { it.category == categories[selectedTabIndex] }
 }
 }

 val unlockedCount = medals.count { it.isUnlocked }
 val totalCount = medals.size

 Column(
 modifier = Modifier.fillMaxSize()
 ) {
 // Encabezado
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .background(
 brush = Brush.verticalGradient(
 colors = listOf(
 MaterialTheme.colorScheme.primaryContainer,
 MaterialTheme.colorScheme.surface
 )
 )
 )
 .padding(16.dp)
 ) {
 Text(
 text = " Álbum de Medallas",
 fontSize = 28.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.onPrimaryContainer
 )

 Spacer(modifier = Modifier.height(8.dp))

 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = "Progreso del Álbum",
 fontSize = 16.sp,
 color = MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f)
 )

 Text(
 text = "$unlockedCount / $totalCount",
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.primary
 )
 }
 }

 // Tabs de categorías
 TabRow(
 selectedTabIndex = selectedTabIndex,
 containerColor = MaterialTheme.colorScheme.surface,
 contentColor = MaterialTheme.colorScheme.onSurface
 ) {
 categories.forEachIndexed { index, category ->
 Tab(
 selected = selectedTabIndex == index,
 onClick = { selectedTabIndex = index },
 text = {
 Text(
 text = category,
 fontSize = 14.sp,
 fontWeight = if (selectedTabIndex == index) FontWeight.Bold else FontWeight.Normal
 )
 }
 )
 }
 }

 // Grid de medallas
 LazyVerticalGrid(
 columns = GridCells.Fixed(2),
 modifier = Modifier
 .fillMaxSize()
 .padding(16.dp),
 verticalArrangement = Arrangement.spacedBy(12.dp),
 horizontalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 items(filteredMedals) { medal ->
 MedalAlbumCard(medal = medal)
 }
 }
 }
}

@Composable
private fun MedalAlbumCard(medal: AlbumMedal) {
 Card(
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp),
 elevation = CardDefaults.cardElevation(4.dp),
 colors = CardDefaults.cardColors(
 containerColor = if (medal.isUnlocked)
 MaterialTheme.colorScheme.surface
 else
 MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
 ),
 shape = RoundedCornerShape(16.dp)
 ) {
 Box(
 modifier = Modifier.fillMaxSize()
 ) {
 Column(
 modifier = Modifier
 .fillMaxSize()
 .padding(12.dp),
 horizontalAlignment = Alignment.CenterHorizontally,
 verticalArrangement = Arrangement.SpaceBetween
 ) {
 // Icono de rareza en la esquina superior
 Box(
 modifier = Modifier
 .size(16.dp)
 .clip(CircleShape)
 .background(medal.rarity.color)
 .align(Alignment.End)
 )

 // Icono principal
 Box(
 modifier = Modifier
 .size(64.dp)
 .clip(CircleShape)
 .background(
 if (medal.isUnlocked) {
 medal.rarity.color.copy(alpha = 0.2f)
 } else {
 Color.Gray.copy(alpha = 0.3f)
 }
 ),
 contentAlignment = Alignment.Center
 ) {
 if (medal.isUnlocked) {
 Icon(
 imageVector = medal.icon,
 contentDescription = null,
 tint = medal.rarity.color,
 modifier = Modifier.size(32.dp)
 )
 } else {
 Icon(
 imageVector = Icons.Default.Lock,
 contentDescription = "Bloqueada",
 tint = Color.Gray,
 modifier = Modifier.size(32.dp)
 )
 }
 }

 // Información de la medalla
 Column(
 horizontalAlignment = Alignment.CenterHorizontally
 ) {
 Text(
 text = if (medal.isUnlocked) medal.name else "???",
 fontSize = 14.sp,
 fontWeight = FontWeight.Bold,
 color = if (medal.isUnlocked)
 MaterialTheme.colorScheme.onSurface
 else
 Color.Gray,
 textAlign = TextAlign.Center,
 maxLines = 2
 )

 Spacer(modifier = Modifier.height(4.dp))

 Text(
 text = medal.rarity.displayName,
 fontSize = 12.sp,
 color = medal.rarity.color,
 fontWeight = FontWeight.Medium
 )

 if (medal.isUnlocked && medal.unlockedDate != null) {
 Spacer(modifier = Modifier.height(4.dp))
 Text(
 text = medal.unlockedDate,
 fontSize = 10.sp,
 color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
 )
 }
 }
 }

 // Efecto de brillo para medallas desbloqueadas de alta rareza
 if (medal.isUnlocked && (medal.rarity == MedalRarity.EPIC || medal.rarity == MedalRarity.LEGENDARY)) {
 Box(
 modifier = Modifier
 .fillMaxSize()
 .background(
 brush = Brush.radialGradient(
 colors = listOf(
 medal.rarity.color.copy(alpha = 0.1f),
 Color.Transparent
 ),
 radius = 100f
 )
 )
 )
 }
 }
 }
