import com.roque.domain.common.UIState
import com.roque.domain.model.Mission
import com.roque.epicmedalsapp.R
import com.roque.epicmedalsapp.core.utils.getIconFromName
import com.roque.epicmedalsapp.ui.composables.ErrorScreen
import com.roque.epicmedalsapp.ui.composables.LoadingScreen

@Composable
fun MissionsScreen(
 missionsViewModel: MissionsViewModel
) {

 val missionsState by missionsViewModel.missionsState.collectAsState()
 val missions by missionsViewModel.missions.collectAsState()

 when(val state = missionsState) {
 is UIState.Loading -> LoadingScreen()
 is UIState.Error -> ErrorScreen(message = state.message, onRetry = { })
 is UIState.Success -> {
 LazyColumn(
 modifier = Modifier
 .fillMaxSize()
 .padding(horizontal = 16.dp),
 verticalArrangement = Arrangement.spacedBy(12.dp)
 ) {
 item {
 Text(
 text = stringResource(R.string.txt_active_missions),
 fontSize = 28.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.onBackground,
 modifier = Modifier.padding(vertical = 16.dp)
 )
 }

 items(missions) { mission ->
 MissionCard(mission = mission)
 }

 item {
 Spacer(modifier = Modifier.height(80.dp))
 }
 }
 }
 }
}

@Composable
private fun MissionCard(mission: Mission) {
 Card(
 modifier = Modifier.fillMaxWidth(),
 elevation = CardDefaults.cardElevation(6.dp),
 colors = CardDefaults.cardColors(
 containerColor = MaterialTheme.colorScheme.surface
 ),
 shape = RoundedCornerShape(16.dp)
 ) {
 Column(
 modifier = Modifier.padding(16.dp)
 ) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 verticalAlignment = Alignment.CenterVertically
 ) {
 Box(
 modifier = Modifier
 .size(48.dp)
 .clip(CircleShape)
 .background(Color(mission.backgroundColor.toColorInt())),
 contentAlignment = Alignment.Center
 ) {
 Icon(
 imageVector = getIconFromName(mission.icon),
 contentDescription = null,
 tint = Color.White,
 modifier = Modifier.size(24.dp)
 )
 }

 Spacer(modifier = Modifier.width(12.dp))

 Column(modifier = Modifier.weight(1f)) {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = mission.title,
 fontSize = 18.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.onSurface
 )

 if (mission.isCompleted) {
 Icon(
 imageVector = Icons.Default.CheckCircle,
 contentDescription = stringResource(R.string.txt_completed),
 tint = Color(0xFF4CAF50),
 modifier = Modifier.size(24.dp)
 )
 } else {
 Box(
 modifier = Modifier
 .clip(RoundedCornerShape(12.dp))
 .background(
 when (mission.difficulty) {
 "Fácil" -> Color(0xFF4CAF50)
 "Medio" -> Color(0xFFFF9800)
 "Difícil" -> Color(0xFFE91E63)
 else -> Color.Gray
 }
 )
 .padding(horizontal = 8.dp, vertical = 4.dp)
 ) {
 Text(
 text = mission.difficulty,
 color = Color.White,
 fontSize = 12.sp,
 fontWeight = FontWeight.Bold
 )
 }
 }
 }

 Text(
 text = mission.description,
 fontSize = 14.sp,
 color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.7f),
 modifier = Modifier.padding(top = 4.dp)
 )
 }
 }

 Spacer(modifier = Modifier.height(16.dp))

 // Progreso
 if (!mission.isCompleted) {
 Column {
 Row(
 modifier = Modifier.fillMaxWidth(),
 horizontalArrangement = Arrangement.SpaceBetween
 ) {
 Text(
 text = stringResource(R.string.txt_progress),
 fontSize = 14.sp,
 fontWeight = FontWeight.Medium,
 color = MaterialTheme.colorScheme.onSurface
 )
 Text(
 text = "${mission.currentProgress}/${mission.maxProgress}",
 fontSize = 14.sp,
 fontWeight = FontWeight.Bold,
 color = MaterialTheme.colorScheme.primary
 )
 }

 Spacer(modifier = Modifier.height(8.dp))

 LinearProgressIndicator(
 progress = { mission.progress },
 modifier = Modifier
 .fillMaxWidth()
 .height(8.dp)
 .clip(RoundedCornerShape(4.dp)),
 color = Color(mission.backgroundColor.toColorInt()),
 trackColor = MaterialTheme.colorScheme.surfaceVariant,
 strokeCap = ProgressIndicatorDefaults.LinearStrokeCap,
 )
 }

 Spacer(modifier = Modifier.height(12.dp))
 }

 // Recompensa
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Icon(
 imageVector = Icons.Default.Star,
 contentDescription = stringResource(R.string.txt_reward),
 tint = Color(0xFFFFD700),
 modifier = Modifier.size(16.dp)
 )
 Spacer(modifier = Modifier.width(6.dp))
 Text(
 text = mission.reward,
 fontSize = 13.sp,
 color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.8f),
 fontWeight = FontWeight.Medium
 )
 }
 }
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Ahora voy a revisar el archivo JSON de misiones y los módulos de inyección de dependencias para identificar problemas:"}],"tool_calls":[{"id":"toolu_bdrk_01JFsfzcD2QxNBCsL9s1Ri9u","type":"function","function":{"name":"read_file","arguments":"{"target_file": "app/src/main/assets/missions.json"}"}},{"id":"toolu_bdrk_01SanLffruP33BzhXguEZcCq","type":"function","function":{"name":"read_file","arguments":"{"target_file": "app/src/main/java/com/roque/epicmedalsapp/core/di/UseCaseModule.kt"}"}},{"id":"toolu_bdrk_017weyZtDUEs9G8vM6iZNWPZ","type":"function","function":{"name":"read_file","arguments":"{"target_file": "app/src/main/java/com/roque/epicmedalsapp/core/di/InterfacesModule.kt"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"toolu_bdrk_01JFsfzcD2QxNBCsL9s1Ri9u","content":"[
